begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated;
select no_plan();
-- Only isolated identities and TEST-only policy references. This fixture never
-- supplies a legal approval for real people or a physical deletion certificate.
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select('a2630000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','erasure263-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,4)i;
insert into public.platform_user_roles(user_id,role_code)values('a2630000-0000-4000-8000-000000000001','COMPLIANCE_MANAGER'),('a2630000-0000-4000-8000-000000000002','COMPLIANCE_MANAGER');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b2630000-0000-4000-8000-000000000001','TEST erasure263','TEST erasure263','ACTIVE','a2630000-0000-4000-8000-000000000001'),('b2630000-0000-4000-8000-000000000002','TEST foreign263','TEST foreign263','ACTIVE','a2630000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status)values('c2630000-0000-4000-8000-000000000001','b2630000-0000-4000-8000-000000000001','a2630000-0000-4000-8000-000000000003','REVOKED');
insert into public.user_profiles(id,display_name,updated_at)values('a2630000-0000-4000-8000-000000000003','TEST personal name263',now()-interval'2 years')on conflict(id)do update set display_name=excluded.display_name,updated_at=excluded.updated_at;
insert into public.data_subject_requests(id,organization_id,request_type,subject_reference_hash,identity_verification_level,locale,status,due_at,verified_at,correlation_id,created_by)values('d2630000-0000-4000-8000-000000000001','b2630000-0000-4000-8000-000000000001','ERASURE',encode(extensions.digest(convert_to('b2630000-0000-4000-8000-000000000001:a2630000-0000-4000-8000-000000000003','UTF8'),'sha256'),'hex'),'ENHANCED','fr-MA','IN_REVIEW',now()+interval'1 day',now()-interval'1 day',extensions.gen_random_uuid(),'a2630000-0000-4000-8000-000000000001');
update private.admin_execution_environment_v1 set environment='DEVELOPMENT',configuration_reference='TEST_ONLY_263_TRUSTED_ENVIRONMENT',configured_at=clock_timestamp()where singleton;
insert into public.organizations(id,legal_name,display_name,status,created_by)select('b2630000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'TEST favorite provider263 '||i,'TEST favorite provider263 '||i,'PENDING','a2630000-0000-4000-8000-000000000001'from generate_series(101,103)i;
insert into public.provider_profiles(provider_organization_id,activity_summary,team_size,years_experience,created_by)select('b2630000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'TEST fixture provider identity only, no qualification',1,0,'a2630000-0000-4000-8000-000000000001'from generate_series(101,103)i;
insert into public.client_provider_favorites(id,client_organization_id,provider_organization_id,status,note,created_by,removed_by,removed_at)values
('f2630000-0000-4000-8000-000000000001','b2630000-0000-4000-8000-000000000001','b2630000-0000-4000-8000-000000000101','REMOVED','TEST own removed personal note','a2630000-0000-4000-8000-000000000003','a2630000-0000-4000-8000-000000000003',now()-interval'2 years'),
('f2630000-0000-4000-8000-000000000002','b2630000-0000-4000-8000-000000000001','b2630000-0000-4000-8000-000000000102','REMOVED','TEST another author note','a2630000-0000-4000-8000-000000000004','a2630000-0000-4000-8000-000000000004',now()-interval'2 years'),
('f2630000-0000-4000-8000-000000000003','b2630000-0000-4000-8000-000000000001','b2630000-0000-4000-8000-000000000103','ACTIVE','TEST active business favorite','a2630000-0000-4000-8000-000000000003',null,null),
('f2630000-0000-4000-8000-000000000004','b2630000-0000-4000-8000-000000000002','b2630000-0000-4000-8000-000000000101','REMOVED','TEST foreign tenant note','a2630000-0000-4000-8000-000000000003','a2630000-0000-4000-8000-000000000003',now()-interval'2 years');
create temporary table er263(k text primary key,v jsonb);grant all on er263 to authenticated;
create function pg_temp.actor263(n integer,aal text default'aal2')returns void language plpgsql as $$declare u text:='a2630000-0000-4000-8000-'||lpad(n::text,12,'0');begin perform set_config('request.jwt.claim.sub',u,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated','aal',aal)::text,true);end$$;
set local role authenticated;select pg_temp.actor263(4);
select throws_ok($$select public.confirm_my_dsr_erasure_scope_v1('d2630000-0000-4000-8000-000000000001',true,'TEST-263-outsider')$$,'42501','DSR_VERIFIED_ERASURE_SUBJECT_REQUIRED','another subject cannot confirm erasure of the verified person');
select pg_temp.actor263(3,'aal1');
select throws_ok($$select public.confirm_my_dsr_erasure_scope_v1('d2630000-0000-4000-8000-000000000001',true,'TEST-263-aal1')$$,'42501','DSR_VERIFIED_ERASURE_SUBJECT_REQUIRED','erasure confirmation requires a fresh MFA session');
select pg_temp.actor263(3);
select throws_ok($$select public.confirm_my_dsr_erasure_scope_v1('d2630000-0000-4000-8000-000000000001',false,'TEST-263-unconfirmed')$$,'22023','DSR_ERASURE_SCOPE_CONFIRMATION_REQUIRED','scope cannot be silently confirmed');
insert into er263 values('scope',public.confirm_my_dsr_erasure_scope_v1('d2630000-0000-4000-8000-000000000001',true,'TEST-263-scope'));
select throws_ok($$select public.create_dsr_erasure_draft_v1('d2630000-0000-4000-8000-000000000001',(select(v->>'scope_version_id')::uuid from er263 where k='scope'),'TEST unauthorized policy author','TEST-263-subject-draft')$$,'42501','DSR_LEGAL_STAFF_REQUIRED','the subject is not made a legal approval authority');
select pg_temp.actor263(1);
insert into er263 values('draft',public.create_dsr_erasure_draft_v1('d2630000-0000-4000-8000-000000000001',(select(v->>'scope_version_id')::uuid from er263 where k='scope'),'TEST fixture dispositions, no real legal approval','TEST-263-draft'));
select throws_ok($$select public.submit_dsr_erasure_plan_v1((select(v->>'draft_id')::uuid from er263 where k='draft'),(select v->>'catalog_hash'from er263 where k='draft'))$$,'55000','DSR_ERASURE_UNCLASSIFIED_SOURCE','every source requires an explicit disposition before sealing');
reset role;
select ok(not has_function_privilege('authenticated','private.dsr_erasure_physical_context_v1(uuid)','EXECUTE'),'private physical authorization is never callable by the API');
select ok(not has_table_privilege('authenticated','public.dsr_erasure_source_receipts_v1','INSERT'),'no browser can manufacture native erasure receipts');
select throws_ok($$select private.dsr_erasure_validate_rule_v1('{"native_action":null}','{"schema_version":2,"action":"ANONYMIZE_DISPLAY_NAME","minimum_age_days":0,"not_before":"2026-01-01T00:00:00Z","retention_until":"2026-01-01T00:00:00Z","authorization_valid_until":"2099-01-01T00:00:00Z","retained_fields_until":"2099-01-01T00:00:00Z","legal_reference":"TEST_POLICY_263","reason":"TEST only classification"}')$$,'22023','DSR_ERASURE_COMMAND_NOT_ALLOWLISTED','source names never authorize an arbitrary destruction command');
create function pg_temp.classify263()returns void language plpgsql as $$declare d uuid:=(select(v->>'draft_id')::uuid from er263 where k='draft');s jsonb;conf jsonb;begin for s in select value from public.dsr_erasure_drafts_v1,jsonb_array_elements(catalog_json)where id=d loop conf:=jsonb_build_object('schema_version',2,'action',case s->>'key'when'public.user_profiles'then'ANONYMIZE_DISPLAY_NAME'when'public.client_provider_favorites'then'ERASE_REMOVED_FAVORITE_NOTES'when'@physical_storage'then'ACTION_REQUIRED'else'RETAIN_LEGAL'end,'minimum_age_days',0,'not_before',clock_timestamp()-interval'1 day','retention_until',clock_timestamp()-interval'1 day','authorization_valid_until',clock_timestamp()+interval'1 year','retained_fields_until',case when s->>'key'='@physical_storage'then null else clock_timestamp()+interval'2 years'end,'legal_reference','TEST_ONLY_263_SYNTHETIC_RETENTION','reason','TEST fixture policy, synthetic records only; identifiers and obligatory records retained explicitly');perform public.configure_dsr_erasure_source_v1(d,s->>'key',0,conf);end loop;end$$;
select pg_temp.classify263();
set local role authenticated;
insert into er263 values('plan',public.submit_dsr_erasure_plan_v1((select(v->>'draft_id')::uuid from er263 where k='draft'),(select v->>'catalog_hash'from er263 where k='draft')));
select throws_ok($$select public.review_dsr_erasure_plan_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),true,true,'TEST_ONLY_263_REVIEW','TEST independent review required')$$,'42501','DSR_ERASURE_INDEPENDENT_REVIEW_REQUIRED','policy author cannot approve their own erasure plan');
select pg_temp.actor263(2);
select throws_ok($$select public.review_dsr_erasure_plan_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),NULL,true,true,'TEST_ONLY_263_REVIEW','TEST null CAS is forbidden')$$,'40001','STALE_DSR_ERASURE_PLAN','null CAS cannot bypass plan binding');
select throws_ok($$select public.review_dsr_erasure_plan_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),true,false,'TEST_ONLY_263_REVIEW','TEST explicit review required')$$,'22023','DSR_ERASURE_DOCUMENTED_POLICY_REVIEW_REQUIRED','approval requires explicit complete policy review');
insert into er263 values('review',public.review_dsr_erasure_plan_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),true,true,'TEST_ONLY_263_REVIEW','TEST synthetic policy review, not a real legal approval'));
reset role;
insert into er263 values('staff_context',private.dsr_erasure_physical_context_v1((select(v->>'plan_id')::uuid from er263 where k='plan')));
select set_config('request.jwt.claim.sub','',true);select set_config('request.jwt.claims','{}',true);
select is(private.dsr_erasure_policy_context_core_v1((select(v->>'plan_id')::uuid from er263 where k='plan')),(select v from er263 where k='staff_context'),'private native-policy core is JWT independent and returns the same frozen context');
select ok(not has_function_privilege('authenticated','private.dsr_erasure_policy_context_core_v1(uuid)','EXECUTE'),'a browser cannot invoke the JWT-independent native guard');
select pg_temp.actor263(2);
select throws_ok($$select private.dsr_erasure_validate_rule_v1('{"native_action":null}','{"action":"RETAIN_LEGAL","minimum_age_days":0,"not_before":"2026-01-01T00:00:00Z","retain_until":"2099-01-01T00:00:00Z","legal_reference":"TEST_POLICY_263","reason":"TEST ambiguous legacy policy"}')$$,'22023','DSR_ERASURE_EXPLICIT_POLICY_V2_REQUIRED','legacy retain_until is never reinterpreted as either retention or authorization');
create function pg_temp.future_retention263()returns text language plpgsql as $$declare newdraft jsonb;newplan jsonb;newreview jsonb;item jsonb;policy_value jsonb;begin
 newdraft:=public.create_dsr_erasure_draft_v1('d2630000-0000-4000-8000-000000000001',(select(v->>'scope_version_id')::uuid from er263 where k='scope'),'TEST minimum legal retention not yet reached','TEST-263-future-retention');
 for item in select value from public.dsr_erasure_plans_v1,jsonb_array_elements(policy_json->'sources')where id=(select(v->>'plan_id')::uuid from er263 where k='plan')loop policy_value:=item->'config';if item->>'source_key'='public.user_profiles'then policy_value:=jsonb_set(policy_value,array['retention_until'],to_jsonb(clock_timestamp()+interval'1 day'));end if;perform public.configure_dsr_erasure_source_v1((newdraft->>'draft_id')::uuid,item->>'source_key',0,policy_value);end loop;
 newplan:=public.submit_dsr_erasure_plan_v1((newdraft->>'draft_id')::uuid,newdraft->>'catalog_hash');perform pg_temp.actor263(1);newreview:=public.review_dsr_erasure_plan_v1((newplan->>'plan_id')::uuid,newplan->>'content_hash',true,true,'TEST_ONLY_263_MINIMUM_RETENTION','TEST independent review does not override minimum legal retention');
 perform public.execute_dsr_erasure_sources_v1((newplan->>'plan_id')::uuid,newplan->>'content_hash',newreview->>'review_proof_hash');return'UNEXPECTED_SUCCESS';exception when others then return sqlerrm;end$$;
select is(pg_temp.future_retention263(),'DSR_ERASURE_MINIMUM_RETENTION_NOT_REACHED','approved authorization cannot erase before the separately defined minimum legal retention date');
create function pg_temp.drift263()returns text language plpgsql as $$begin update public.user_profiles set display_name='TEST changed after review'where id='a2630000-0000-4000-8000-000000000003';perform public.execute_dsr_erasure_sources_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),(select v->>'review_proof_hash'from er263 where k='review'));return'UNEXPECTED_SUCCESS';exception when others then return sqlerrm;end$$;
select is(pg_temp.drift263(),'STALE_DSR_ERASURE_TARGET','a changed profile is never erased under an earlier snapshot approval');
create function pg_temp.hold263()returns text language plpgsql as $$begin insert into public.privacy_legal_holds(organization_id,subject_reference_hash,reason_code,status,starts_at,evidence_reference,created_by)select organization_id,subject_reference_hash,'TEST_ONLY','ACTIVE',now()-interval'1 day','TEST_ONLY_263_HOLD','a2630000-0000-4000-8000-000000000001'from public.data_subject_requests where id='d2630000-0000-4000-8000-000000000001';perform public.execute_dsr_erasure_sources_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),(select v->>'review_proof_hash'from er263 where k='review'));return'UNEXPECTED_SUCCESS';exception when others then return sqlerrm;end$$;
select is(pg_temp.hold263(),'PRIVACY_LEGAL_HOLD_ACTIVE','a newly active legal hold blocks every native effect');
create function pg_temp.shared263()returns text language plpgsql as $$begin insert into public.organization_memberships(organization_id,user_id,status)values('b2630000-0000-4000-8000-000000000002','a2630000-0000-4000-8000-000000000003','REVOKED');perform public.execute_dsr_erasure_sources_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),(select v->>'review_proof_hash'from er263 where k='review'));return'UNEXPECTED_SUCCESS';exception when others then return sqlerrm;end$$;
select is(pg_temp.shared263(),'DSR_ERASURE_SHARED_OR_CURRENT_PROFILE_REQUIRED','a global profile remains protected when another organization has a historical membership');
create function pg_temp.deleted_author263()returns text language plpgsql as $$begin update auth.users set deleted_at=clock_timestamp()where id='a2630000-0000-4000-8000-000000000001';perform public.execute_dsr_erasure_sources_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),(select v->>'review_proof_hash'from er263 where k='review'));return'UNEXPECTED_SUCCESS';exception when others then return sqlerrm;end$$;
select is(pg_temp.deleted_author263(),'DSR_ERASURE_POLICY_AUTHORITY_REVOKED','a soft-deleted policy author cannot authorize a future effect even while role rows remain');
create function pg_temp.revoked_reviewer263()returns text language plpgsql as $$begin update public.platform_user_roles set revoked_at=clock_timestamp()where user_id='a2630000-0000-4000-8000-000000000001'and role_code='COMPLIANCE_MANAGER';perform public.execute_dsr_erasure_sources_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),(select v->>'review_proof_hash'from er263 where k='review'));return'UNEXPECTED_SUCCESS';exception when others then return sqlerrm;end$$;
select is(pg_temp.revoked_reviewer263(),'DSR_ERASURE_POLICY_AUTHORITY_REVOKED','retired policy-author authority is rechecked at execution');
set local role authenticated;
insert into er263 values('effect',public.execute_dsr_erasure_sources_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),(select v->>'review_proof_hash'from er263 where k='review')));
select is((select(v->>'complete')::boolean from er263 where k='effect'),false,'native erasure does not falsely certify physical/external copies');
insert into er263 values('replay',public.execute_dsr_erasure_sources_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),(select v->>'review_proof_hash'from er263 where k='review')));
select is((select v from er263 where k='replay'),(select v from er263 where k='effect'),'repeating execution returns the same native receipt without erasing twice');
insert into er263 values('report',public.prepare_dsr_erasure_report_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan')));
select is((select(v->>'complete')::boolean from er263 where k='report'),false,'missing physical/external evidence keeps the report partial');
select throws_ok($$select public.review_dsr_erasure_report_v1((select(v->>'execution_id')::uuid from er263 where k='report'),(select v->>'sha256'from er263 where k='report'),true,'TEST report needs another reviewer')$$,'42501','DSR_ERASURE_INDEPENDENT_REPORT_REVIEW_REQUIRED','execution report author cannot publish their own proof');
select pg_temp.actor263(1);
select lives_ok($$select public.review_dsr_erasure_report_v1((select(v->>'execution_id')::uuid from er263 where k='report'),(select v->>'sha256'from er263 where k='report'),true,'TEST explicit partial report review and protected retained fields')$$,'another legal actor can publish the truthful partial report');
select pg_temp.actor263(4);
select throws_ok($$select public.get_private_dsr_erasure_report_v1((select(v->>'execution_id')::uuid from er263 where k='report'))$$,'42501','DSR_PRIVATE_ERASURE_REPORT_DENIED','foreign subjects cannot download erasure proofs');
select pg_temp.actor263(3);
select throws_ok($$select public.acknowledge_my_dsr_erasure_report_v1((select(v->>'execution_id')::uuid from er263 where k='report'),(select(v->>'scope_version_id')::uuid from er263 where k='scope'),(select v->>'sha256'from er263 where k='report'))$$,'55000','DSR_ERASURE_REVIEWED_REPORT_ACCESS_REQUIRED','a subject cannot ACK bytes they have not opened');
insert into er263 values('opened',public.get_private_dsr_erasure_report_v1((select(v->>'execution_id')::uuid from er263 where k='report')));
select lives_ok($$select public.acknowledge_my_dsr_erasure_report_v1((select(v->>'execution_id')::uuid from er263 where k='report'),(select(v->>'scope_version_id')::uuid from er263 where k='scope'),(select v->>'sha256'from er263 where k='report'))$$,'the revoked organization member can acknowledge their own exact proof');
select pg_temp.actor263(1);
select throws_ok($$select public.transition_data_subject_request('d2630000-0000-4000-8000-000000000001',1,'FULFILLED','TEST_ONLY_PARTIAL_ERASURE','privacy-erasure:'||(select v->>'execution_id'from er263 where k='report'),extensions.gen_random_uuid())$$,'55000','PRIVACY_FULL_ERASURE_EVIDENCE_REQUIRED','review and ACK of a partial report cannot fake full erasure');
reset role;
select is((select display_name from public.user_profiles where id='a2630000-0000-4000-8000-000000000003'),'Utilisateur anonymisé','the approved native command actually removes the synthetic personal name');
select is((select count(*)from public.dsr_erasure_source_receipts_v1 where plan_id=(select(v->>'plan_id')::uuid from er263 where k='plan')),2::bigint,'each native source has one immutable execution receipt after replay');
select is((select count(*)from public.event_outbox where event_type='DsrErasureSourceExecutedV1'and payload->>'plan_id'=(select v->>'plan_id'from er263 where k='plan')),2::bigint,'one Outbox fact is persisted for each actual native effect');
select ok(not exists(select 1 from public.event_outbox where payload->>'plan_id'=(select v->>'plan_id'from er263 where k='plan')and payload::text like'%TEST personal name263%'),'erased personal values never enter the Outbox');
select is((select status from public.data_subject_requests where id='d2630000-0000-4000-8000-000000000001'),'IN_REVIEW','the request honestly remains in review while coverage is incomplete');
select is((select note from public.client_provider_favorites where id='f2630000-0000-4000-8000-000000000001'),null::text,'the reviewed removed personal favorite note is really erased');
select is((select note from public.client_provider_favorites where id='f2630000-0000-4000-8000-000000000002'),'TEST another author note','another person in the same organization remains unchanged');
select is((select note from public.client_provider_favorites where id='f2630000-0000-4000-8000-000000000003'),'TEST active business favorite','active shared business favorites are not silently erased');
select is((select note from public.client_provider_favorites where id='f2630000-0000-4000-8000-000000000004'),'TEST foreign tenant note','the same subject in another tenant remains out of scope');
set local role authenticated;
select lives_ok($$select public.get_dsr_erasure_console_v1(true,'d2630000-0000-4000-8000-000000000001',(select(v->>'draft_id')::uuid from er263 where k='draft'),(select(v->>'plan_id')::uuid from er263 where k='plan'),1,'')$$,'real paginated console projections compile with a sealed plan and source rules');
select lives_ok($$select public.revoke_dsr_erasure_plan_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),'TEST stop all future erasure effects explicitly')$$,'a legal actor can revoke the exact plan without pretending to undo past effects');
select throws_ok($$select public.execute_dsr_erasure_sources_v1((select(v->>'plan_id')::uuid from er263 where k='plan'),(select v->>'content_hash'from er263 where k='plan'),(select v->>'review_proof_hash'from er263 where k='review'))$$,'55000','DSR_ERASURE_POLICY_REVOKED','revocation is checked before idempotent replay or any new effect');
reset role;
select * from finish();
rollback;
